CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('ADMIN','SALES'); CREATE TYPE quote_status AS ENUM ('DRAFT','SENT','ACCEPTED','REJECTED'); CREATE TYPE order_status AS ENUM ('PENDING','CONFIRMED','DISPATCHED','CANCELLED');
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL UNIQUE,password_hash text NOT NULL,role user_role NOT NULL DEFAULT 'SALES',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,contact_person text,phone text,email text,city text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,name text NOT NULL,category text NOT NULL,unit text NOT NULL,base_price numeric(12,2) NOT NULL CHECK(base_price>=0),active boolean NOT NULL DEFAULT true);
CREATE TABLE inventory(product_id uuid PRIMARY KEY REFERENCES products(id),physical_qty integer NOT NULL DEFAULT 0 CHECK(physical_qty>=0),reserved_qty integer NOT NULL DEFAULT 0 CHECK(reserved_qty>=0 AND reserved_qty<=physical_qty),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE enquiries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),enquiry_number bigint GENERATED ALWAYS AS IDENTITY UNIQUE,customer_id uuid NOT NULL REFERENCES customers(id),enquiry_date date NOT NULL DEFAULT CURRENT_DATE,required_date date NOT NULL,status text NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','IN_REVIEW','QUOTED','CLOSED')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE enquiry_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),enquiry_id uuid NOT NULL REFERENCES enquiries(id) ON DELETE CASCADE,product_id uuid NOT NULL REFERENCES products(id),quantity integer NOT NULL CHECK(quantity>0),notes text);
CREATE TABLE quotations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quote_number bigint GENERATED ALWAYS AS IDENTITY UNIQUE,enquiry_id uuid NOT NULL REFERENCES enquiries(id),customer_id uuid NOT NULL REFERENCES customers(id),valid_until date NOT NULL,status quote_status NOT NULL DEFAULT 'DRAFT',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quotation_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quotation_id uuid NOT NULL REFERENCES quotations(id) ON DELETE CASCADE,product_id uuid NOT NULL REFERENCES products(id),quantity integer NOT NULL CHECK(quantity>0),unit_price numeric(12,2) NOT NULL CHECK(unit_price>=0),discount_pct numeric(5,2) NOT NULL DEFAULT 0 CHECK(discount_pct BETWEEN 0 AND 100),tax_pct numeric(5,2) NOT NULL DEFAULT 0 CHECK(tax_pct BETWEEN 0 AND 100));
CREATE TABLE sales_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_number bigint GENERATED ALWAYS AS IDENTITY UNIQUE,quotation_id uuid NOT NULL UNIQUE REFERENCES quotations(id),customer_id uuid NOT NULL REFERENCES customers(id),order_date date NOT NULL DEFAULT CURRENT_DATE,total_amount numeric(14,2) NOT NULL CHECK(total_amount>=0),status order_status NOT NULL DEFAULT 'PENDING',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sales_order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sales_order_id uuid NOT NULL REFERENCES sales_orders(id) ON DELETE CASCADE,product_id uuid NOT NULL REFERENCES products(id),quantity integer NOT NULL CHECK(quantity>0),unit_price numeric(12,2) NOT NULL CHECK(unit_price>=0));
CREATE TABLE dispatches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),dispatch_number bigint GENERATED ALWAYS AS IDENTITY UNIQUE,sales_order_id uuid NOT NULL UNIQUE REFERENCES sales_orders(id),dispatch_date timestamptz NOT NULL DEFAULT now(),vehicle_number text NOT NULL,driver_name text NOT NULL);
CREATE INDEX enquiries_customer_idx ON enquiries(customer_id); CREATE INDEX quotations_status_idx ON quotations(status); CREATE INDEX orders_status_idx ON sales_orders(status); CREATE INDEX quote_items_quote_idx ON quotation_items(quotation_id); CREATE INDEX order_items_order_idx ON sales_order_items(sales_order_id);
